13.query:
fetch bizevents, from:now()-1h
| filter `event.provider` == "banco.core"
| summarize sucesso = countIf(status == "success"), erro = countIf(status == "error"), by:{bin(timestamp, 1m)}

21.query:
fetch bizevents, from:now()-6h
| filter `event.provider` == "banco.fraude"
| summarize tentativas = count(), bloqueadas = countIf(status == "blocked"), by:{bin(timestamp, 15m)}
